# Now check for rectangles
rects = []
for r in range(H):
    for c in range(W):
        if uniform_grid[r][c] == 1:
            # Find extent
            max_c = c
            while max_c + 1 < W and uniform_grid[r][max_c + 1] == 1:
                max_c += 1

            max_r = r
            while max_r + 1 < H and uniform_grid[max_r + 1][c] == 1:
                max_r += 1

            # Check if bottom-right corner exists
            if max_r == r or uniform_grid[max_r][max_c] == 1:
                # Verify it's a valid rectangle
                # Left side
                left_valid = True
                for rr in range(r, max_r + 1):
                    if uniform_grid[rr][c] != 1:
                        left_valid = False
                        break

                # Right side
                right_valid = True
                for rr in range(r, max_r + 1):
                    if uniform_grid[rr][max_c] != 1:
                        right_valid = False
                        break

                if left_valid:
                    if max_r == r:
                        # Single row
                        rects.append((r, r, c, max_c))
                    else:
                        # Multi-row
                        rects.append((r, max_r, c, max_c))

# Remove duplicates
seen = set()
unique_rects = []
for rec in rects:
    if rec not in seen:
        seen.add(rec)
        unique_rects.append(rec)

